import {deliveryItems} from './business.js?v=booking-15';
export const deliveryStatuses=['Not set','No','In progress','Partial','Yes','Not required'];
const lines=v=>[...new Set((Array.isArray(v)?v:String(v||'').split('\n')).map(x=>String(x).trim()).filter(Boolean))];
export function itemText(i){return (i.quantity?i.quantity+' × ':'')+i.label+(i.duration?' ('+i.duration+')':'');}
export function packageDeliverables(p,kind='deliverable'){return p.delivery?.items?p.delivery.items.filter(i=>i.kind===kind).map(itemText):kind==='complimentary'?(p.complimentary||[]):(p.deliverables||[]);}
export function syncPackageDelivery(p,previous=p.delivery?.items||[]){const items=[];for(const [kind,labels] of [['deliverable',lines(p.deliverables)],['complimentary',lines(p.complimentary)]]){const old=previous.filter(i=>i.kind===kind),used=new Set();for(const [index,label] of labels.entries()){let item=old.find(i=>itemText(i)===label&&!used.has(i.id));if(!item&&old.length===labels.length&&old[index]&&!used.has(old[index].id)&&!labels.includes(old[index].label))item=old[index];if(item)used.add(item.id);items.push({...item,id:item?.id||crypto.randomUUID(),kind,label:item&&itemText(item)===label?item.label:label,status:item?.status||'Not set'});}}const removed=previous.filter(i=>!items.some(x=>x.id===i.id));p.delivery={...p.delivery,items};if(removed.length)p.delivery.retiredItems=[...(p.delivery.retiredItems||[]),...removed];p.deliverables=items.filter(i=>i.kind==='deliverable').map(itemText);p.complimentary=items.filter(i=>i.kind==='complimentary').map(itemText);}
function aliases(label){if(['Bride Album','Groom Album','Bride TV','Groom TV'].includes(label))return [label];if(/countdown/i.test(label))return ['Countdown'];if(/raw/i.test(label))return ['Raw Data'];if(/reel/i.test(label))return ['Reels'];if(/selected.*(image|photo)|edited.*(image|photo)|image.*editing|photo.*edit|\bphotos\b/i.test(label))return ['Photos'];if(/photobook|album/i.test(label))return ['Bride Album','Groom Album'];if(/traditional.*video|full.length/i.test(label))return ['Bride TV','Groom TV'];if(/teaser.*highlight/i.test(label))return ['Teaser','Highlight'];if(/teaser/i.test(label))return ['Teaser'];if(/highlight/i.test(label))return ['Highlight'];return [];}
function importedInvoiceNote(p){return /^(?:Invoice \d{6} — (?:on-event payment received|booking payment dated)|Original invoice \d{6} dated .*: 20% booking payment)/i.test(String(p.notes||''));}
export function cleanPaymentNotes(p){if(importedInvoiceNote(p))return 'Verified against original invoice.';return String(p.notes||'').replace(/Payment date was not recorded in the source\.?/gi,'').replace(/Original invoice (\d+): on-event receipt\.?/gi,'Original invoice $1.').replace(/Payment date was not provided\.?/gi,'').replace(/Imported original booking receipt\.?/gi,'Imported original receipt.').trim();}
export function migrateDeliveryData(data){let changed=false;for(const p of data.packages||[]){const events=data.events.filter(e=>p.events.includes(e.id));if(!p.delivery?.items){const legacy=events.filter(e=>e.delivery).map(e=>({event:e.id,data:structuredClone(e.delivery)}));if(!p.deliverables?.length){const custom=events.flatMap(e=>lines(e.delivery?.requirements));p.deliverables=custom.length?[...new Set(custom)]:events.length?[...deliveryItems]:[];}p.complimentary ||= [];syncPackageDelivery(p);p.delivery.legacyEvents=legacy;for(const item of p.delivery.items){const values=events.flatMap(source=>{const d=source.delivery||{},keys=d.requirements?.trim()?lines(d.requirements):Object.keys(d);const exact=keys.find(k=>k===item.label),candidates=exact?[exact]:aliases(item.label);const matching=exact?[exact]:keys.filter(k=>candidates.includes(k)||aliases(k).some(a=>candidates.includes(a)));const statuses=matching.filter(k=>deliveryStatuses.includes(d[k])).map(k=>d[k]);return statuses.length?statuses:['Not set'];});if(values.length&&new Set(values).size===1)item.status=values[0];else if(values.some(s=>s==='Yes'))item.needsReview=true;}const links=[...new Set(legacy.map(x=>x.data.drive).filter(Boolean))];if(links.length===1)p.delivery.drive=links[0];changed=true;}for(const item of p.delivery.items){if(item.needsReview&&item.status==='Not set'&&['Bride Album','Groom Album','Bride TV','Groom TV'].includes(item.label)){const sources=p.delivery.legacyEvents||[];const values=sources.map(x=>x.data[item.label]||'Not set');if(sources.length===events.length&&values.length&&new Set(values).size===1){item.status=values[0];delete item.needsReview;changed=true;}}}const authoritative=packageDeliverables(p),gifts=packageDeliverables(p,'complimentary');if(JSON.stringify(p.deliverables)!==JSON.stringify(authoritative)||JSON.stringify(p.complimentary)!==JSON.stringify(gifts)){p.deliverables=authoritative;p.complimentary=gifts;changed=true;}for(const e of events){if(e.delivery){p.delivery.legacyEvents ||= [];if(!p.delivery.legacyEvents.some(x=>x.event===e.id))p.delivery.legacyEvents.push({event:e.id,data:structuredClone(e.delivery)});delete e.delivery;changed=true;}if(e.deliveryPackage!==p.id){e.deliveryPackage=p.id;changed=true;}}}
for(const e of data.events){if(e.deliveryPackage&&!data.packages?.some(p=>p.id===e.deliveryPackage&&p.events.includes(e.id))){delete e.deliveryPackage;changed=true;}}
for(const p of data.payments){if(importedInvoiceNote(p)&&!p.reference){p.reference=String(p.notes).match(/invoice (\d{6})/i)?.[1]||'';changed=true;}const notes=cleanPaymentNotes(p);if(notes!==String(p.notes||'')){data.paymentNoteCleanup ||= [];data.paymentNoteCleanup.push({payment:p.id,before:p.notes,after:notes});p.notes=notes;changed=true;}}
if(data.deliverySchema!==2){data.deliverySchema=2;changed=true;}return changed;}
export function protectedClient(data,id){return data.payments.some(p=>p.client===id)||(data.invoices||[]).some(i=>i.client===id)||(data.packages||[]).some(p=>p.client===id);}
export function deliveryGroups(data,clientId){const packages=(data.packages||[]).filter(p=>!clientId||p.client===clientId);const linked=new Set((data.packages||[]).flatMap(p=>p.events));return [...packages.map(p=>({kind:'package',record:p})),...data.events.filter(e=>(!clientId||e.client===clientId)&&!linked.has(e.id)).map(e=>({kind:'event',record:e}))];}
